// The header field use_po writes, as in fields-view's PO handling.
export const PO_FIELD = 'purchase_order';
export const OPEN_SCREENS = ['po_match', 'accounting', 'document', 'settings', 'validation'];
export const MAX_BULK_FIELDS = 10;

const RESULT_TIMEOUT_MS = 10_000;
// A tab switch mounts the table first.
const TABLE_TIMEOUT_MS = 15_000;

export type AssistantAction = AssistantActionPayload;
export type AssistantFinding = AssistantFindingPayload;
export type AssistantTier = AssistantCapabilities['tier'];

// The field state captured before a change, restored on undo.
export type FieldSnapshot = Record<string, unknown>;

export interface FieldActionResult {
  ok: boolean;
  reason?: string;
  previous?: FieldSnapshot;
  applied?: unknown;
  // false when nothing changed that undo could take back (e.g. a search dialog opened)
  undoable?: boolean;
  // what changed, for session_changes and the applied line
  changes?: SessionChangeDraft[];
  // a message key the panel shows after a step that is not a form change
  notice?: string;
}

export interface FieldActionResultDetail extends FieldActionResult {
  requestId: string;
}

export interface ActionContext {
  router?: Router;
  // fields that block validation, in form order
  openFields?: string[];
  // the field the assistant focused last
  lastField?: string | null;
}

export interface ValidationAssistantActionHandler {
  labelKey: string;
  minTier: AssistantTier;
  // Changes the form: gets an applied-change line, and undo if defined.
  changesForm: boolean;
  // kind-specific fields from the frame, or null when they are unusable
  normalize: (data: Record<string, unknown>) => Partial<AssistantAction> | null;
  run: (action: AssistantAction, ctx?: ActionContext) => Promise<FieldActionResult>;
  undo?: (action: AssistantAction, result: FieldActionResult) => Promise<FieldActionResult>;
}

let requestCounter = 0;

function nextRequestId(): string {
  requestCounter += 1;
  return `va-${Date.now()}-${requestCounter}`;
}

// Dispatches a request event and waits for the screen's result event with the same requestId.
export function requestFieldAction(
  eventName: string,
  detail: Record<string, unknown>,
  timeoutMs: number = RESULT_TIMEOUT_MS,
): Promise<FieldActionResult> {
  const requestId = nextRequestId();
  return new Promise((resolve) => {
    let timer: ReturnType<typeof setTimeout> | null = null;
    const onResult = (event: Event) => {
      const result = (event as CustomEvent<FieldActionResultDetail>).detail;
      if (!result || result.requestId !== requestId) return;
      document.removeEventListener(FIELD_ACTION_RESULT_EVENT, onResult);
      if (timer) clearTimeout(timer);
      resolve({
        ok: !!result.ok,
        reason: result.reason,
        previous: result.previous,
        applied: result.applied,
        ...(result.undoable === false ? { undoable: false } : {}),
        ...(Array.isArray(result.changes) ? { changes: result.changes } : {}),
        ...(typeof result.notice === 'string' ? { notice: result.notice } : {}),
      });
    };
    document.addEventListener(FIELD_ACTION_RESULT_EVENT, onResult);
    timer = setTimeout(() => {
      document.removeEventListener(FIELD_ACTION_RESULT_EVENT, onResult);
      resolve({ ok: false, reason: 'no_response' });
    }, timeoutMs);
    document.dispatchEvent(
      new CustomEvent(eventName, { detail: { ...detail, requestId } }),
    );
  });
}

// Called by the screen to answer a request.
export function replyFieldAction(requestId: string, result: FieldActionResult) {
  document.dispatchEvent(
    new CustomEvent(FIELD_ACTION_RESULT_EVENT, { detail: { ...result, requestId } }),
  );
}

function restore(action: AssistantAction, result: FieldActionResult) {
  return requestFieldAction(RESTORE_FIELD_EVENT, {
    field: action.field,
    previous: result.previous,
    expected: result.applied,
  });
}

function restoreFields(_action: AssistantAction, result: FieldActionResult) {
  return requestFieldAction(RESTORE_FIELDS_EVENT, {
    previous: result.previous,
    expected: result.applied,
  });
}

function fire(eventName: string, detail: Record<string, unknown>): FieldActionResult {
  document.dispatchEvent(new CustomEvent(eventName, { detail }));
  return { ok: true };
}

async function navigate(router: Router | undefined, path: unknown): Promise<FieldActionResult> {
  if (!router || !isResolvableAppPath(router, path)) return { ok: false, reason: 'invalid_path' };
  await router.push(path);
  return { ok: true };
}

// The next blocking field after the one focused last, wrapping around.
export function nextOpenField(openFields: string[] | undefined, lastField?: string | null): string | null {
  const fields = openFields || [];
  if (!fields.length) return null;
  const index = lastField ? fields.indexOf(lastField) : -1;
  return fields[(index + 1) % fields.length] ?? null;
}

export interface BulkItem {
  field: string;
  label: string;
  result: FieldActionResult;
}

export function summarizeBulk(items: BulkItem[]) {
  const confirmed = items.filter((item) => item.result.ok);
  return {
    confirmed: confirmed.length,
    total: items.length,
    failed: items
      .filter((item) => !item.result.ok)
      .map((item) => ({ field: item.field, label: item.label, reason: item.result.reason || 'failed' })),
  };
}

const str = (value: unknown) => (typeof value === 'string' && value.trim() ? value : undefined);
const optStr = (value: unknown) => value === undefined || value === null || typeof value === 'string';
const index = (value: unknown) =>
  typeof value === 'number' && Number.isInteger(value) && value >= 0 ? value : undefined;

function stringRecord(value: unknown): Record<string, string> | undefined {
  if (!value || typeof value !== 'object' || Array.isArray(value)) return undefined;
  const entries = Object.entries(value as Record<string, unknown>);
  if (!entries.length || entries.some(([key, v]) => !key || typeof v !== 'string')) return undefined;
  return Object.fromEntries(entries) as Record<string, string>;
}

function fieldList(value: unknown, max: number): { field: string; label: string }[] | undefined {
  if (!Array.isArray(value) || !value.length || value.length > max) return undefined;
  const out: { field: string; label: string }[] = [];
  for (const item of value) {
    const field = str(item?.field ?? item?.field_name);
    if (!field || out.some((known) => known.field === field)) return undefined;
    out.push({ field, label: str(item?.label) || field });
  }
  return out;
}

function fillList(value: unknown): { field: string; label: string; display: string }[] | undefined {
  if (!Array.isArray(value)) return undefined;
  const out: { field: string; label: string; display: string }[] = [];
  for (const item of value) {
    const field = str(item?.field);
    if (!field) return undefined;
    out.push({
      field,
      label: str(item?.label) || field,
      display: typeof item?.display === 'string' ? item.display : '',
    });
  }
  return out;
}

const needsField = (data: Record<string, unknown>) => (str(data.field) ? {} : null);

function tableTarget(data: Record<string, unknown>) {
  const table = str(data.table);
  const row_index = index(data.row_index);
  const column = str(data.column);
  if (!table || row_index === undefined || !column) return null;
  return { table, row_index, column, column_label: str(data.column_label) || column };
}

export const VALIDATION_ASSISTANT_ACTIONS: Record<string, ValidationAssistantActionHandler> = {
  go_to_field: {
    labelKey: 'validation_assistant_jump_to_field',
    minTier: 'viewer',
    changesForm: false,
    normalize: needsField,
    run: async (action) =>
      fire(FOCUS_BLOCKED_FIELD_EVENT, { field_name: action.field }),
  },
  set_value: {
    labelKey: 'validation_assistant_action_set_value',
    minTier: 'editor',
    changesForm: true,
    normalize: (data) => (str(data.field) && typeof data.value === 'string' ? {} : null),
    run: (action) =>
      requestFieldAction(SET_FIELD_VALUE_EVENT, {
        field: action.field,
        value: action.value,
      }),
    undo: restore,
  },
  confirm_field: {
    labelKey: 'validation_assistant_action_confirm',
    minTier: 'editor',
    changesForm: true,
    normalize: needsField,
    run: (action) => requestFieldAction(CONFIRM_FIELD_EVENT, { field: action.field }),
    undo: restore,
  },
  go_to_table_cell: {
    labelKey: 'validation_assistant_jump_to_cell',
    minTier: 'viewer',
    changesForm: false,
    normalize: tableTarget,
    run: (action) =>
      requestFieldAction(
        GO_TO_TABLE_CELL_EVENT,
        { table: action.table, row_index: action.row_index, column: action.column },
        TABLE_TIMEOUT_MS,
      ),
  },
  set_table_cell: {
    labelKey: 'validation_assistant_action_set_value',
    minTier: 'editor',
    changesForm: true,
    normalize: (data) => {
      const target = tableTarget(data);
      if (!target || typeof data.value !== 'string') return null;
      return target;
    },
    run: (action) =>
      requestFieldAction(
        SET_TABLE_CELL_EVENT,
        {
          table: action.table,
          row_index: action.row_index,
          column: action.column,
          column_label: action.column_label,
          value: action.value,
          current_display: action.current_display,
        },
        TABLE_TIMEOUT_MS,
      ),
    undo: (action, result) =>
      requestFieldAction(
        RESTORE_TABLE_CELL_EVENT,
        { table: action.table, previous: result.previous, expected: result.applied },
        TABLE_TIMEOUT_MS,
      ),
  },
  add_table_row: {
    labelKey: 'validation_assistant_action_add_row',
    minTier: 'editor',
    changesForm: true,
    normalize: (data) => {
      const table = str(data.table);
      const preset = stringRecord(data.preset);
      if (!table || !preset) return null;
      return { table, preset, display: str(data.display) };
    },
    run: (action) =>
      requestFieldAction(
        ADD_TABLE_ROW_EVENT,
        { table: action.table, preset: action.preset },
        TABLE_TIMEOUT_MS,
      ),
    undo: (action, result) =>
      requestFieldAction(
        REMOVE_TABLE_ROW_EVENT,
        { table: action.table, previous: result.previous },
        TABLE_TIMEOUT_MS,
      ),
  },
  apply_lookup_candidate: {
    labelKey: 'validation_assistant_action_apply_candidate',
    minTier: 'editor',
    changesForm: true,
    normalize: (data) => {
      const candidate_index = index(data.candidate_index);
      const fills = fillList(data.fills ?? []);
      if (!str(data.field) || candidate_index === undefined || !fills) return null;
      return { candidate_index, fills, candidate_display: str(data.candidate_display) };
    },
    run: (action) =>
      requestFieldAction(APPLY_LOOKUP_CANDIDATE_EVENT, {
        field: action.field,
        candidate_index: action.candidate_index,
        fills: action.fills,
      }),
    undo: restoreFields,
  },
  rerun_lookup: {
    labelKey: 'validation_assistant_action_rerun_lookup',
    minTier: 'editor',
    changesForm: true,
    normalize: needsField,
    run: (action) => requestFieldAction(RERUN_LOOKUP_EVENT, { field: action.field }),
    undo: restoreFields,
  },
  use_po: {
    labelKey: 'validation_assistant_action_use_po',
    minTier: 'editor',
    changesForm: true,
    normalize: (data) => {
      const po_number = str(data.po_number);
      if (!po_number) return null;
      return { field: PO_FIELD, po_number, value: po_number, display_value: str(data.display) || po_number };
    },
    run: (action) =>
      requestFieldAction(SET_FIELD_VALUE_EVENT, { field: PO_FIELD, value: action.po_number }),
    undo: (action, result) => restore({ ...action, field: PO_FIELD }, result),
  },
  open_screen: {
    labelKey: 'validation_assistant_action_open_screen',
    minTier: 'viewer',
    changesForm: false,
    normalize: (data) => {
      const screen = str(data.screen);
      const path = str(data.path);
      if (!screen || !OPEN_SCREENS.includes(screen) || !path) return null;
      if (!optStr(data.doc_id)) return null;
      return { screen, path, doc_id: str(data.doc_id) };
    },
    run: (action, ctx) => navigate(ctx?.router, action.path),
  },
  reclassify: {
    labelKey: 'validation_assistant_action_reclassify',
    minTier: 'editor',
    changesForm: false,
    normalize: (data) => {
      const doc_type = str(data.doc_type);
      if (!doc_type) return null;
      return { doc_type, doc_type_label: str(data.doc_type_label) || doc_type };
    },
    run: (action) => requestFieldAction(RECLASSIFY_EVENT, { doc_type: action.doc_type }),
  },
  next_open_field: {
    labelKey: 'validation_assistant_question_next_field',
    minTier: 'viewer',
    changesForm: false,
    normalize: () => ({}),
    run: async (_action, ctx) => {
      const field = nextOpenField(ctx?.openFields, ctx?.lastField);
      if (!field) return { ok: false, reason: 'none_open' };
      fire(FOCUS_BLOCKED_FIELD_EVENT, { field_name: field });
      return { ok: true, applied: field };
    },
  },
  bulk_confirm: {
    labelKey: 'validation_assistant_action_confirm_all',
    minTier: 'editor',
    changesForm: true,
    normalize: (data) => {
      const fields = fieldList(data.fields, MAX_BULK_FIELDS);
      return fields ? { fields } : null;
    },
    run: async (action) => {
      const items: BulkItem[] = [];
      for (const { field, label } of action.fields || []) {
        items.push({ field, label, result: await requestFieldAction(CONFIRM_FIELD_EVENT, { field }) });
      }
      const summary = summarizeBulk(items);
      if (!summary.confirmed) {
        return { ok: false, reason: summary.failed[0]?.reason || 'failed' };
      }
      const confirmed = items.filter((item) => item.result.ok);
      return {
        ok: true,
        previous: Object.fromEntries(confirmed.map((item) => [item.field, item.result.previous])),
        applied: summary,
        changes: confirmed.map((item) => ({ field: item.field, label: item.label, kind: 'confirm_field' as const })),
      };
    },
    undo: async (_action, result) => {
      const previous = (result.previous || {}) as Record<string, unknown>;
      let failed: string | undefined;
      for (const field of Object.keys(previous).reverse()) {
        const undone = await requestFieldAction(RESTORE_FIELD_EVENT, {
          field,
          previous: previous[field],
        });
        if (!undone.ok) failed = failed ?? undone.reason;
      }
      return failed ? { ok: false, reason: failed } : { ok: true };
    },
  },
  start_field_training: {
    labelKey: 'validation_assistant_action_train_field',
    minTier: 'editor',
    changesForm: false,
    normalize: needsField,
    run: (action) => requestFieldAction(START_FIELD_TRAINING_EVENT, { field: action.field }),
  },
  suggest_rule: {
    labelKey: 'validation_assistant_action_open_rule_editor',
    minTier: 'admin',
    changesForm: false,
    normalize: (data) => {
      const path = str(data.path);
      const description = str(data.description);
      if (!path || !description) return null;
      const target_field = str(data.target_field);
      return {
        path,
        description,
        target_field,
        target_label: str(data.target_label) || target_field,
      };
    },
    run: (action, ctx) => navigate(ctx?.router, action.path),
  },
  create_support_ticket: {
    labelKey: 'create_ticket',
    minTier: 'viewer',
    changesForm: false,
    normalize: (data) => {
      const subject = str(data.subject);
      if (!subject || !optStr(data.body)) return null;
      return { subject, body: str(data.body) || '' };
    },
    run: async (action) =>
      fire(OPEN_SUPPORT_TICKET_EVENT, { subject: action.subject, body: action.body }),
  },
  create_task: {
    labelKey: 'add_a_task',
    minTier: 'editor',
    changesForm: false,
    normalize: (data) => {
      const title = str(data.title);
      if (!title || !optStr(data.body)) return null;
      return { title, body: str(data.body) || '' };
    },
    run: async (action) => fire(OPEN_TASK_FORM_EVENT, { title: action.title, body: action.body }),
  },
};

export function actionHandler(kind: string): ValidationAssistantActionHandler | null {
  return Object.prototype.hasOwnProperty.call(VALIDATION_ASSISTANT_ACTIONS, kind)
    ? VALIDATION_ASSISTANT_ACTIONS[kind]
    : null;
}

const TIER_RANK: Record<AssistantTier, number> = { viewer: 0, editor: 1, admin: 2 };

// Buttons only when the server's rights allow it; form-changing kinds never on a read-only screen.
export function canRunAssistantAction(
  kind: string,
  capabilities: AssistantCapabilities,
  readOnly: boolean,
): boolean {
  const handler = actionHandler(kind);
  if (!handler) return false;
  if ((TIER_RANK[capabilities.tier] ?? 0) < TIER_RANK[handler.minTier]) return false;
  if (handler.minTier === 'admin') return capabilities.can_see_setup;
  if (handler.minTier === 'editor') return !readOnly && capabilities.can_change_fields;
  return true;
}

// A usable action of a known kind, or null (unknown kinds and malformed frames are dropped).
export function normalizeAssistantAction(raw: unknown): AssistantAction | null {
  if (!raw || typeof raw !== 'object') return null;
  const data = { ...(raw as Record<string, unknown>) };
  if (data.field === undefined && data.field_name !== undefined) data.field = data.field_name;
  const kind = data.kind;
  if (typeof kind !== 'string') return null;
  const handler = actionHandler(kind);
  if (!handler) return null;
  if (typeof data.label !== 'string' || !data.label) return null;
  for (const key of ['field', 'section', 'value', 'display_value', 'current_display', 'reason_code', 'reason']) {
    if (!optStr(data[key])) return null;
  }
  const extra = handler.normalize(data);
  if (!extra) return null;
  const field = (extra.field as string) ?? (str(data.field) || '');
  const action: AssistantAction = {
    id: typeof data.id === 'string' && data.id ? data.id : `${kind}:${field || data.label}`,
    kind,
    field,
    label: data.label,
    section: (data.section as string) || undefined,
    value: (data.value as string) ?? undefined,
    display_value: (data.display_value as string) ?? undefined,
    current_display: (data.current_display as string) ?? undefined,
    reason_code: (data.reason_code as string) || undefined,
    reason: (data.reason as string) || undefined,
  };
  for (const [key, value] of Object.entries(extra)) {
    if (value !== undefined) (action as unknown as Record<string, unknown>)[key] = value;
  }
  return action;
}

const FINDING_SEVERITIES = ['info', 'warning', 'error'];
const ADMIN_KEYS: (keyof AssistantFindingAdmin)[] = [
  'detail',
  'script_label',
  'trigger',
  'rule_label',
  'setting_key',
  'setting_label',
  'deep_link',
];

function normalizeFindingAdmin(raw: unknown): AssistantFindingAdmin | undefined {
  if (!raw || typeof raw !== 'object') return undefined;
  const data = raw as Record<string, unknown>;
  const admin: AssistantFindingAdmin = {};
  for (const key of ADMIN_KEYS) {
    const value = data[key];
    if (typeof value === 'string' && value.trim()) admin[key] = value;
  }
  return Object.keys(admin).length ? admin : undefined;
}

// A usable finding, or null (malformed frames and unknown severities are dropped).
export function normalizeAssistantFinding(raw: unknown): AssistantFinding | null {
  if (!raw || typeof raw !== 'object') return null;
  const data = raw as Record<string, unknown>;
  const { severity, title, message, area } = data;
  if (typeof severity !== 'string' || !FINDING_SEVERITIES.includes(severity)) return null;
  if (typeof title !== 'string' || !title) return null;
  if (typeof message !== 'string') return null;
  if (typeof area !== 'string' || !area) return null;
  if (!optStr(data.field) || !optStr(data.label) || !optStr(data.path)) return null;
  const fields = normalizeFindingFields(data.fields);
  return {
    id: typeof data.id === 'string' && data.id ? data.id : `${area}:${title}`,
    severity: severity as AssistantFinding['severity'],
    title,
    message,
    area,
    field: (data.field as string) || undefined,
    label: (data.label as string) || undefined,
    path: (data.path as string) || undefined,
    ...(fields ? { fields } : {}),
    admin: normalizeFindingAdmin(data.admin),
  };
}

// CORE-6161: malformed entries are dropped, an empty list means no chips.
function normalizeFindingFields(raw: unknown): { name: string; label: string }[] | undefined {
  if (!Array.isArray(raw)) return undefined;
  const fields = raw
    .filter((entry): entry is Record<string, unknown> => !!entry && typeof entry === 'object')
    .filter((entry) => typeof entry.name === 'string' && !!entry.name)
    .map((entry) => ({
      name: entry.name as string,
      label: typeof entry.label === 'string' && entry.label ? entry.label : (entry.name as string),
    }));
  return fields.length ? fields : undefined;
}

const TIERS = ['viewer', 'editor', 'admin'];

// Anything but an explicit true is treated as "not allowed".
export function normalizeAssistantCapabilities(raw: unknown): AssistantCapabilities {
  const data = raw && typeof raw === 'object' ? (raw as Record<string, unknown>) : {};
  return {
    tier: TIERS.includes(data.tier as string)
      ? (data.tier as AssistantCapabilities['tier'])
      : 'viewer',
    can_change_fields: data.can_change_fields === true,
    can_see_setup: data.can_see_setup === true,
  };
}
